INSERT INTO public.programmes (
  slug, university_id, name, level, field, duration, campus, intakes, international_fee, specialisations,
  source_url, verified_at, study_mode, international_fee_amount, fee_currency, fee_period,
  english_requirements_en, accreditation, application_notes_en
)
SELECT
  p.slug, u.id, p.name, p.level, p.field, p.duration, p.campus, p.intakes, p.international_fee, p.specialisations,
  p.source_url, p.verified_at, p.study_mode, p.fee_amount, p.fee_currency, p.fee_period,
  p.english_requirements_en, p.accreditation, p.application_notes_en
FROM programme_data p
JOIN public.universities u ON u.slug = p.university_slug
ON CONFLICT (slug) DO UPDATE SET
  university_id = EXCLUDED.university_id,
  name = EXCLUDED.name,
  level = EXCLUDED.level,
  field = EXCLUDED.field,
  duration = EXCLUDED.duration,
  campus = EXCLUDED.campus,
  intakes = EXCLUDED.intakes,
  international_fee = EXCLUDED.international_fee,
  specialisations = EXCLUDED.specialisations,
  source_url = EXCLUDED.source_url,
  verified_at = EXCLUDED.verified_at,
  study_mode = EXCLUDED.study_mode,
  international_fee_amount = EXCLUDED.international_fee_amount,
  fee_currency = EXCLUDED.fee_currency,
  fee_period = EXCLUDED.fee_period,
  english_requirements_en = EXCLUDED.english_requirements_en,
  accreditation = EXCLUDED.accreditation,
  application_notes_en = EXCLUDED.application_notes_en,
  updated_at = now();

